"""Explain byte order, fallthrough and word-count boundaries."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1933': ('같은 숫자 조각도 어느 조각을 큰 자리에 놓느냐에 따라 다른 수가 돼요. 바이트 순서와 읽을 주소의 정렬은 서로 다른 문제예요.', '정렬되지 않은 읽기와 바이트 순서, 모델의 범위를 구분합니다.', '주소 순서의 바이트 01·02·03·04를 작은 자리부터 읽으면 0x04030201, 큰 자리부터 읽으면 0x01020304라고 적으세요.', ['바이트는 8비트의 메모리 단위이고 u32는 4바이트 정수예요. 정렬은 정수를 읽을 시작 주소를 정해진 간격에 맞추는 것이에요. 예를 들어 4바이트 경계에 맞지 않는 주소에서 네 바이트를 읽는 상황을 unaligned, 즉 정렬되지 않은 읽기라고 불러요.', 'jhash의 중간 반복문은 __get_unaligned_cpu32를 사용해요. 이 도우미는 __packed 구조체를 통해 정렬되지 않은 주소의 u32를 읽는 표현을 제공해요. 컴파일러와 기종에 맞는 코드로 처리하도록 하는 것이며 아무 잘못된 주소나 읽어도 된다는 뜻은 아니에요. 필요한 바이트가 실제로 읽을 수 있는 범위에 있어야 해요.', 'endian은 여러 바이트를 어느 순서로 정수의 자리에 놓는지에 대한 약속이에요. 주소 순서가 01·02·03·04라면 작은 자리부터 두는 리틀엔디언은 0x04030201, 큰 자리부터 두는 빅엔디언은 0x01020304로 해석해요. 0x는 16진수 표시예요.', '중간 반복문의 CPU32 읽기는 실행하는 CPU의 바이트 순서로 값을 읽어요. 마지막 tail은 남은 부분이라는 뜻인데, 이 부분은 k[i]라는 개별 바이트를 읽어 8·16·24비트 이동해서 상태에 더해요. 두 부분의 읽기 표현이 같다고 추측하지 말고 코드를 나누어 봐요.', '원문은 jhash 결과가 바이트 순서에 의존한다고 적어요. 따라서 같은 바이트 입력이면 모든 기종에서 무조건 같은 결과가 나온다고 보장하면 안 돼요. 한편 모든 길이와 모든 입력이 반드시 다른 결과가 된다는 뜻도 아니에요.', '실험에서 bswap으로 바이트 순서를 뒤집으면 다른 순서로 읽은 값을 모형으로 비교할 수 있어요. bswap은 바이트 자리 바꾸기예요. 이것만으로 실제 빅엔디언 CPU의 명령이나 모든 자료 배치 규약을 실행한 것은 아니에요. 숫자 해석 모델과 실제 기종 검증의 범위를 구별해요.'], [('bswap으로 빅엔디언 읽기를 흉내 낸 모형을 계산하면 실제 빅엔디언 커널을 실행한 것인가요?', ['네. 모든 빅엔디언 기종을 실행한 것이에요', '아니요. 바이트 읽기 순서를 바꾼 모형이에요'], '정답은 두 번째예요. 숫자가 구성되는 순서를 비교할 수 있지만 실제 CPU 명령과 자료 배치까지 모두 시험한 것은 아니에요.'), ('jhash의 마지막 tail은 바이트들을 상태 값에 어떻게 더하나요?', ['개별 바이트를 읽고 필요한 비트 수만큼 이동해 더해요', '항상 전체 CPU32 읽기 도우미만 호출해요'], '정답은 첫 번째예요. switch에 k[index]와 <<8·<<16·<<24가 있어요. 중간 반복문의 네 바이트 읽기와 마지막 바이트 조립을 구별하세요.')]), 'os1934': ('계단의 다섯 번째 칸에서 내려오기 시작하면 다섯째 칸만 밟고 끝나는 것이 아니에요. 이 switch도 들어간 위치부터 아래 처리를 이어서 해요.', 'fallthrough로 남은 바이트를 빠짐없이 누적하는 흐름을 이해합니다.', '남은 길이 5이면 case 5→4→3→2→1→final→break를 그리세요.', ['switch는 값에 맞는 case 위치에서 실행을 시작하는 C 문장이에요. 보통 각 case 끝에서 break로 빠져나오는 예를 배우지만, 이 코드는 의도적으로 아래 case로 이어져요. fallthrough는 다음 처리로 계속 내려간다는 표시예요.', '남은 길이 5이면 case 5에서 시작해 b에 k[4]를 더해요. 배열 번호는 0부터 시작하므로 k[4]는 다섯 번째 바이트예요. 그다음 break가 없어서 case 4·3·2·1의 동작도 이어서 실행해요.', 'case 4부터는 a에 k[3]을 24비트, k[2]를 16비트, k[1]을 8비트 옮겨 더하고 마지막으로 k[0]을 그대로 더해요. 원래 입력의 처음 네 바이트를 a에, 다섯째 바이트를 b에 반영하는 것이에요.', '입력 바이트가 1·2·3·4·5라고 가정하면 a에 더하는 묶음은 0x04030201이고 b에는 5를 더해요. 기존 a·b 값을 0으로 새로 만드는 것이 아니라 초기 상태나 중간 계산값에 이 양을 더해요. 이후 final에서 또 섞어요.', 'case 1에서는 첫 바이트를 더한 뒤 __jhash_final을 부르고 break로 switch를 나가요. case 0은 더할 바이트가 없어 바로 break해요. 빈 입력도 무조건 final을 거친다고 외우면 이 분기를 놓쳐요.', '각 case에 임의로 break를 넣으면 길이 5에서 다섯 번째 바이트만 반영하고 앞의 네 바이트를 빠뜨리게 돼요. 아래로 이어지는 것이 실수가 아니라 모든 남은 바이트를 반영하려는 설계예요. 입력 길이와 실제 읽는 마지막 배열 번호를 함께 따라가세요.'], [('길이 5인 tail은 b에 바이트 하나만 더하고 바로 끝나나요?', ['네. 모든 case 끝에 break가 있어요', '아니요. 아래 case로 이어져 a에도 앞의 네 바이트를 더해요'], '정답은 두 번째예요. case 5 뒤에 fallthrough가 있어 4·3·2·1을 계속 실행해요. case 하나만 선택해서 그 부분만 실행한다고 생각하면 남은 바이트를 빠뜨려요.'), ('tail 길이 0에서 final을 실행하나요?', ['아니요. case 0은 바로 break해요', '네. 길이와 관계없이 언제나 실행해요'], '정답은 첫 번째예요. final은 case 1 쪽에 있고 case 0에는 없어요. 빈 입력의 이 분기에서는 상태를 추가로 섞지 않아요.')]), 'os1935': ('연필 세 자루와 연필의 총길이는 다른 숫자예요. 함수에 길이를 줄 때도 항목 개수인지 바이트 수인지 먼저 확인해야 해요.', 'jhash2의 원소 개수와 초기식의 바이트 환산을 구분합니다.', 'u32 세 개는 길이 인수 3, 전체 메모리 양은 3×4=12바이트라고 두 칸에 나누어 적으세요.', ['jhash2는 u32 배열을 받는 함수예요. u32는 부호 없는 32비트 정수 하나로, 메모리 4바이트를 사용해요. 이 함수의 length는 바이트 수가 아니라 배열에 들어 있는 u32 항목 개수예요.', '배열이 [10,20,30]이라면 항목은 세 개이므로 length에 3을 줘요. 전체 메모리 양은 12바이트지만 jhash2에 12를 주면 12개 항목이 있다고 알리는 셈이에요. 실제 배열보다 더 읽으려 할 수 있으므로 단위 혼동을 피해야 해요.', '초기 상태에는 JHASH_INITVAL+(length<<2)+initval을 사용해요. 왼쪽 두 칸 이동은 유효한 작은 값에서 4배이므로 세 항목이면 12를 더해요. 호출할 때는 개수 3을 받고 함수 안의 초기식에서 바이트 양 12를 반영하는 구조예요.', 'k[0]·k[1]·k[2]는 바이트 하나가 아니라 정수 하나씩 읽어요. k += 3도 3바이트 이동이 아니라 u32 세 개, 즉 12바이트 앞으로 가는 표현이에요. 포인터가 가리키는 타입에 따라 한 칸 이동의 크기가 달라져요.', 'jhash2에는 정렬 조건을 갖춘 실제 u32 배열과 유효한 개수를 넘겨야 해요. 바이트 배열을 임의 주소에서 u32 포인터로 바꾸기만 해도 모든 기종에서 안전해진다고 생각하지 않아요. 바이트를 처리하는 jhash와 인수의 타입 및 읽기 방식을 구별해요.', '이 초기식은 32비트 정수 계산이므로 아주 큰 length의 이동까지 무한히 큰 정수의 곱셈처럼 다루지는 않아요. 이 수업에서는 실제 유효한 작은 배열로 단위를 연습해요. 같은 메모리를 jhash에 넘길 때의 바이트 수 12와 jhash2의 개수 3을 비교하되 모든 기종에서 결과도 같다고 일반화하지 않아요.'], [('u32 항목이 세 개 있는 배열을 jhash2에 넘길 때 length는 얼마인가요?', ['12예요', '3이에요'], '정답은 두 번째예요. 이 함수가 요구하는 단위는 항목 개수예요. 12는 이 배열의 바이트 크기이며 그대로 넘기면 12개 항목이 있다고 잘못 알리는 셈이에요.'), ('초기식의 length<<2는 무엇을 반영하나요?', ['u32 개수를 4배해 바이트 길이를 반영해요', '언제나 길이 1비트를 뜻해요'], '정답은 첫 번째예요. u32 하나가 4바이트이므로 세 개는 12바이트예요. 인수 단위와 초기 계산에서 쓰는 단위를 나누어 이해하세요.')]), 'os1936': ('세 개씩 처리하되 마지막 세 개 이하를 남겨 별도로 마무리해요. 여섯 개라면 중간 처리 한 번과 마지막 처리 한 번으로 나뉘어요.', 'jhash2의 반복 횟수와 마지막 항목 배치를 이해합니다.', '입력 4개는 반복 1번·남은 1개, 6개는 반복 1번·남은 3개, 7개는 반복 2번·남은 1개라고 적으세요.', ['여기서 word는 u32 항목 하나, 즉 4바이트 정수를 뜻해요. jhash2는 length > 3일 때 세 항목씩 중간 처리해요. 정확히 3개 남으면 조건이 거짓이 되어 반복을 멈춰요.', '한 번 반복할 때 k[0]을 a에, k[1]을 b에, k[2]를 c에 더하고 mix를 실행해요. 이어 length에서 3을 빼고 포인터 k를 항목 세 개 앞으로 옮겨요. 남은 양과 다음에 읽을 위치가 함께 바뀌어요.', '여섯 항목은 6→3으로 줄어 중간 mix 한 번 뒤 멈춰요. 네 항목은 4→1로 한 번, 일곱 항목은 7→4→1로 두 번이에요. 세 개짜리 묶음이 두 개 있다는 이유만으로 여섯 항목의 중간 mix가 두 번이라고 세면 안 돼요.', '마지막 두 항목이 남으면 case 2에서 두 번째 항목 k[1]을 b에 더하고, 아래 case 1로 이어져 첫 항목 k[0]을 a에 더해요. 그 뒤 final로 마무리해요. c에 두 값을 모두 더하는 코드가 아니에요.', '세 항목이면 c에 세 번째, b에 두 번째, a에 첫 번째를 더한 뒤 final해요. 한 항목이면 a에만 더한 뒤 final하고, 0이면 추가 섞기 없이 끝나요. 이 위치 배분으로 입력의 순서가 계산에 반영돼요.', '배열 [10,20]을 임의로 [20,10]으로 바꾸면 a와 b에 더하는 값이 바뀌어요. 같은 숫자 집합이라는 이유로 같은 hash를 기대하면 안 돼요. 다만 해시는 충돌할 수 있으므로 순서를 바꾸면 모든 경우에 반드시 다른 값이라고 보장하는 것도 아니에요.'], [('여섯 u32 항목을 처리할 때 while 안의 중간 mix는 몇 번 실행하나요?', ['언제나 두 번이에요', '한 번이에요'], '정답은 두 번째예요. 6에서 3을 빼면 3이고 3 > 3은 거짓이에요. 마지막 세 항목은 switch와 final로 처리해요.'), ('마지막 두 항목은 어느 상태에 더하나요?', ['b에 두 번째, a에 첫 번째를 더해요', 'c에 두 항목을 모두 더해요'], '정답은 첫 번째예요. case 2의 b += k[1] 다음에 case 1의 a += k[0]이 이어져요. 배열의 순서와 각 상태가 맡는 위치를 확인하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_479.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
